# List all files in refine skill directory recursively
import os

def list_files_recursive(path, indent=0):
    for root, dirs, files in os.walk(path):
        # Remove path prefix from display
        rel = os.path.relpath(root, path)
        if "." in rel:
            rel = ""
        print(" " * indent + f"DIR:  {rel}/" if dirs else " " * indent + f"FILE: {rel}/")
        for f in files:
            print(" " * indent + f"FILE: {rel}{f}")

